from vlb_traj import Session
import numpy as np, json

def move(s,pos,quat,grip=(0.,0.),n=40):
 r=s.ik(pos,quat)
 if not r.get('success'):
  print('IK_FAIL',pos,r); return False
 goal=np.asarray(r['joint_positions'],float); cur=np.asarray(s.state()['robot']['joint_positions'],float)
 for t in np.linspace(0,1,n): s.step(np.r_[cur*(1-t)+goal*t,grip])
 return True

def brief(s):
 st=s.state(); return {'pear':st['entities']['pear_inside']['position'],'tcp':st['robot']['tcp_position'],'fingers':st['robot']['gripper_positions']}
with Session() as s:
 s.record_start(); st=s.state(); p=np.array(st['entities']['pear_inside']['position']); q=np.array(st['robot']['tcp_quaternion_wxyz'])
 move(s,p+[0,0,.13],q,(.04,.04),40)
 move(s,p+[0,0,.015],q,(.04,.04),40)
 for _ in range(40): s.step(np.r_[s.state()['robot']['joint_positions'],[0,0]])
 for h in [.04,.08,.12,.18,.25]:
  move(s,p+[0,0,h],q,(0,0),30)
  for _ in range(10): s.step(np.r_[s.state()['robot']['joint_positions'],[0,0]])
 print('HELD',json.dumps(brief(s)))
 dest=np.array(s.state()['entities']['plate_seen']['get_place_point'][0])
 delta=np.array([.007,-.007,-.057])
 high=np.array([dest[0]+delta[0],dest[1]+delta[1],1.08])
 print('MOVE_HIGH',move(s,high,q,(0,0),70),json.dumps(brief(s)))
 final=np.array([dest[0]+delta[0],dest[1]+delta[1],.98])
 print('LOWER',move(s,final,q,(0,0),45),json.dumps(brief(s)))
 for _ in range(20): s.step(np.r_[s.state()['robot']['joint_positions'],[0,0]])
 for _ in range(15): s.step(np.r_[s.state()['robot']['joint_positions'],[.04,.04]])
 for _ in range(100): s.step(np.r_[s.state()['robot']['joint_positions'],[.04,.04]])
 print('RELEASED',json.dumps(brief(s)))
 print('STATUS',json.dumps(s.status()))
 actions=s.record_stop(); print('N',len(actions)); s.save_trajectory(actions,'/app/output/trajectory.npz')
